class Solution:
    def bowlSubarrays(self, nums):
        st = []; ans = 0
        for r, x in enumerate(nums):
            popped = False
            while st and nums[st[-1]] < x:
                if len(st) >= 2 and r - st[-2] >= 2:
                    ans += 1
                st.pop(); popped = True
            if not popped and st and r - st[-1] >= 2:
                ans += 1
            st.append(r)
        return ans

