class Solution {
public:
    long long bowlSubarrays(vector<int>& nums) {
        vector<int> st; long long ans = 0;
        for (int r = 0; r < (int)nums.size(); r++) {
            bool popped = false;
            while (!st.empty() && nums[st.back()] < nums[r]) {
                if (st.size() >= 2 && r - st[st.size() - 2] >= 2) ans++;
                st.pop_back(); popped = true;
            }
            if (!popped && !st.empty() && r - st.back() >= 2) ans++;
            st.push_back(r);
        }
        return ans;
    }
};

