class Solution {
    public long bowlSubarrays(int[] nums) {
        Deque<Integer> st = new ArrayDeque<>(); long ans = 0;
        for (int r = 0; r < nums.length; r++) {
            boolean popped = false;
            while (!st.isEmpty() && nums[st.peekLast()] < nums[r]) {
                Iterator<Integer> it = st.descendingIterator(); it.next();
                if (it.hasNext() && r - it.next() >= 2) ans++;
                st.pollLast(); popped = true;
            }
            if (!popped && !st.isEmpty() && r - st.peekLast() >= 2) ans++;
            st.addLast(r);
        }
        return ans;
    }
}

