var bowlSubarrays = function(nums) {
    const st = []; let ans = 0;
    for (let r = 0; r < nums.length; r++) {
        const x = nums[r]; let popped = false;
        while (st.length && nums[st[st.length - 1]] < x) {
            if (st.length >= 2 && r - st[st.length - 2] >= 2) ans++;
            st.pop(); popped = true;
        }
        if (!popped && st.length && r - st[st.length - 1] >= 2) ans++;
        st.push(r);
    }
    return ans;
};
